use std::collections::HashMap;
use std::path::Path;

use anyhow::{Context, Result};
use async_trait::async_trait;
use sqlx::{Row, SqlitePool};

use crate::source::{escape_service_name, projection_path, NodeDescriptor, NodeType, ProjectionSource};

const NS: &str = "state";
const DEFAULT_DATABASE_URL: &str = "sqlite:///var/lib/op-dbus/state.db";

/// Primary source: projects the persisted live object graph from state.db.
pub struct StateDbSource {
    database_url: String,
}

impl StateDbSource {
    pub fn new(database_url: impl Into<String>) -> Self {
        Self { database_url: database_url.into() }
    }

    pub fn with_default_database_url() -> Self {
        let database_url = std::env::var("OP_DBUS_DATABASE_URL")
            .unwrap_or_else(|_| DEFAULT_DATABASE_URL.to_string());
        Self::new(database_url)
    }

    fn db_exists(&self) -> bool {
        match self.database_url.strip_prefix("sqlite://") {
            Some(":memory:") => true,
            Some(path) => Path::new(path).exists(),
            None => true,
        }
    }

    async fn connect(&self) -> Result<SqlitePool> {
        SqlitePool::connect(&self.database_url)
            .await
            .with_context(|| format!("connect state db {}", self.database_url))
    }
}

#[async_trait]
impl ProjectionSource for StateDbSource {
    fn name(&self) -> &str { "state-db" }
    fn namespace(&self) -> &str { NS }

    async fn discover(&self) -> Result<Vec<NodeDescriptor>> {
        if !self.db_exists() {
            return Ok(Vec::new());
        }

        let pool = self.connect().await?;
        let rows = sqlx::query(
            r#"
            SELECT ns.service_name, lo.object_path, lo.object_class, lo.state, lo.metadata
            FROM live_objects lo
            JOIN namespace_services ns ON ns.id = lo.service_id
            WHERE ns.enabled = 1
            ORDER BY ns.service_name, lo.object_path
            "#,
        )
        .fetch_all(&pool)
        .await
        .context("query live_objects")?;

        let mut nodes = Vec::with_capacity(rows.len());
        for row in rows {
            let service_name: String = row.get("service_name");
            let object_path: String = row.get("object_path");
            let object_class: String = row.get("object_class");
            let state: String = row.get("state");
            let metadata: Option<String> = row.try_get("metadata").ok();

            let namespace = format!("{NS}/{}", escape_service_name(&service_name));
            let mut properties = HashMap::new();
            properties.insert("_service".into(), service_name.clone());
            properties.insert("_class".into(), object_class);

            if let Ok(value) = serde_json::from_str::<serde_json::Value>(&state) {
                match value {
                    serde_json::Value::Object(map) => {
                        for (key, value) in map {
                            properties.insert(key, value.to_string());
                        }
                    }
                    other => {
                        properties.insert("state".into(), other.to_string());
                    }
                }
            } else {
                properties.insert("state".into(), state);
            }

            if let Some(metadata) = metadata {
                properties.insert("_metadata".into(), metadata);
            }

            nodes.push(NodeDescriptor {
                key: format!("state-db/{service_name}::{object_path}"),
                source_path: format!("sqlite://live_objects::{service_name}{object_path}"),
                dbus_path: projection_path(&namespace, &object_path),
                node_type: NodeType::DbusObject,
                properties,
                children: vec![],
            });
        }

        Ok(nodes)
    }
}

