/// Generic D-Bus object published for every projected node.
/// Implements `org.opdbus.Projection.Node`.
pub struct ProjectedObject {
    pub state: Arc<RwLock<ProjectedState>>,
}

impl ProjectedObject {
    pub fn new(
        source: impl Into<String>,
        source_path: impl Into<String>,
        node_type: NodeType,
        properties: HashMap<String, String>,
        children: Vec<String>,
    ) -> Self {
        Self {
            state: Arc::new(RwLock::new(ProjectedState {
                source: source.into(),
                source_path: source_path.into(),
                node_type,
                properties,
                children,
            })),
        }
    }

    pub fn shared_state(&self) -> Arc<RwLock<ProjectedState>> {
        Arc::clone(&self.state)
    }
}

