use anyhow::Result;
use async_trait::async_trait;
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use tokio::sync::mpsc;

/// A single node in the projected tree.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct NodeDescriptor {
    /// Stable key for deduplication: `"{namespace}::{source_path}"`.
    pub key: String,
    /// Original path in the source system.
    pub source_path: String,
    /// D-Bus object path where this node is published.
    pub dbus_path: String,
    pub node_type: NodeType,
    /// Properties as JSON-encoded string values.
    pub properties: HashMap<String, String>,
    /// D-Bus paths of direct children.
    pub children: Vec<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub enum NodeType {
    /// A live component from ComponentRegistry (agent, plugin, tool, MCP server…).
    RegistryComponent,
    /// A D-Bus object with interfaces (supplemental introspection).
    DbusObject,
    /// A D-Bus service root container.
    DbusService,
    /// A process entry from procfs.
    Process,
    /// A file-backed metric (e.g. /proc/meminfo).
    Metric,
    /// A directory / namespace container.
    Directory,
    /// Collection too large to project inline. Published as
    /// `org.opdbus.Projection.LazyCollection` with paged/on-demand access.
    /// Must carry `"_count"` and `"_source_key"` properties.
    LazyCollection,
}

impl std::fmt::Display for NodeType {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        let s = match self {
            NodeType::RegistryComponent => "registry_component",
            NodeType::DbusObject => "dbus_object",
            NodeType::DbusService => "dbus_service",
            NodeType::Process => "process",
            NodeType::Metric => "metric",
            NodeType::Directory => "directory",
            NodeType::LazyCollection => "lazy_collection",
        };
        f.write_str(s)
    }
}

#[derive(Debug, Clone)]
pub struct ChangeEvent {
    pub source_name: String,
    pub key: String,
    pub kind: ChangeKind,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ChangeKind {
    Added,
    Removed,
    Updated,
}

/// Implemented by every projection plugin.
#[async_trait]
pub trait ProjectionSource: Send + Sync + 'static {
    fn name(&self) -> &str;
    /// Namespace segment appended to `/org/opdbus/projection/`.
    fn namespace(&self) -> &str;
    /// Full discovery scan — engine diffs against previous snapshot.
    async fn discover(&self) -> Result<Vec<NodeDescriptor>>;

    fn supports_watch(&self) -> bool {
        false
    }

    async fn watch(&self) -> Result<mpsc::Receiver<ChangeEvent>> {
        let (_tx, rx) = mpsc::channel(1);
        Ok(rx)
    }
}

// ── Path utilities ────────────────────────────────────────────────────────────

/// Escape a D-Bus service name so it can be used as a path element.
pub fn escape_service_name(name: &str) -> String {
    name.chars()
        .map(|c| match c {
            'A'..='Z' | 'a'..='z' | '0'..='9' | '_' => c,
            _ => '_',
        })
        .collect()
}

/// Build the projected D-Bus path for a namespace + relative path.
pub fn projection_path(namespace: &str, relative: &str) -> String {
    if relative == "/" || relative.is_empty() {
        format!("/org/opdbus/projection/{}", namespace)
    } else if relative.starts_with('/') {
        format!("/org/opdbus/projection/{}{}", namespace, relative)
    } else {
        format!("/org/opdbus/projection/{}/{}", namespace, relative)
    }
}

#[cfg(test)]
mod tests {
    use super::projection_path;

    #[test]
    fn projection_path_does_not_trail_slash_for_root() {
        assert_eq!(
            projection_path("registry", "/"),
            "/org/opdbus/projection/registry"
        );
        assert_eq!(
            projection_path("dbus/system/org_example_Service", ""),
            "/org/opdbus/projection/dbus/system/org_example_Service"
        );
    }

    #[test]
    fn projection_path_preserves_non_root_relative_paths() {
        assert_eq!(
            projection_path("procfs", "/system/memory"),
            "/org/opdbus/projection/procfs/system/memory"
        );
        assert_eq!(
            projection_path("procfs", "system/memory"),
            "/org/opdbus/projection/procfs/system/memory"
        );
    }
}

