use std::collections::{HashMap, HashSet, VecDeque};
use std::sync::Arc;
use std::time::Duration;

use anyhow::{Context, Result};
use async_trait::async_trait;
use dashmap::DashSet;
use tracing::debug;
use zbus::fdo::{DBusProxy, IntrospectableProxy};
use zbus::zvariant::OwnedValue;
use zbus::Connection;

use crate::source::{escape_service_name, projection_path, NodeDescriptor, NodeType, ProjectionSource};

const INTROSPECT_TIMEOUT: Duration = Duration::from_secs(5);
const MAX_DEPTH: usize = 24;
const MAX_DISCOVERED_PATHS: usize = 8192;

const ALWAYS_SKIP_EXACT: &[&str] = &[
    // Skip self-projection to avoid recursively mirroring the projection tree
    // back into itself on every refresh.
    "org.opdbus.Projection",
];

const ALWAYS_SKIP_PREFIXES: &[&str] = &[
    "org.freedesktop.DBus",
    // Core systemd unit manager excluded by design.
    // login1 / machine1 kept: polkit and session depend on them.
    "org.freedesktop.systemd1",
];

