// ── Internal ──────────────────────────────────────────────────────────────────

#[derive(Clone, Copy)]
enum BusKind { System, Session }

struct BusSource {
    kind: BusKind,
    skiplist: Arc<DashSet<String>>,
}

impl BusSource {
    async fn connect(&self) -> Result<Connection> {
        match self.kind {
            BusKind::System => Connection::system().await.context("system bus"),
            BusKind::Session => Connection::session().await.context("session bus"),
        }
    }

    fn should_skip(&self, svc: &str) -> bool {
        ALWAYS_SKIP_EXACT.iter().any(|name| svc == *name)
            || ALWAYS_SKIP_PREFIXES.iter().any(|prefix| svc.starts_with(prefix))
            || self.skiplist.contains(svc)
    }

    fn should_skip_path(&self, service: &str, path: &str) -> bool {
        // The legacy org.opdbus mirror at /org/opdbus/projected is already a
        // projection of other services. Re-projecting it duplicates objects
        // rather than exposing the real owned objects on the system.
        service == "org.opdbus"
            && (path == "/org/opdbus/projected" || path.starts_with("/org/opdbus/projected/"))
    }

    async fn discover(&self, namespace: &str) -> Result<Vec<NodeDescriptor>> {
        let conn = self.connect().await?;
        let dbus = DBusProxy::new(&conn).await?;
        let names = dbus.list_names().await?;
        let mut nodes = Vec::new();

        for name in names {
            let svc = name.as_str();
            if self.should_skip(svc) {
                continue;
            }
            match self.crawl_service(&conn, svc, namespace).await {
                Ok(mut discovered) => nodes.append(&mut discovered),
                Err(e) => debug!("skip {svc}: {e}"),
            }
        }
        Ok(nodes)
    }

    async fn crawl_service(
        &self,
        conn: &Connection,
        service: &str,
        namespace: &str,
    ) -> Result<Vec<NodeDescriptor>> {
        let ns = format!("{}/{}", namespace, escape_service_name(service));
        let paths = self.discover_service_paths(conn, service).await;
        let mut nodes = Vec::new();

        for path in paths {
            if self.should_skip_path(service, &path) {
                continue;
            }

            match self.introspect_node(conn, service, &path, &ns).await {
                Ok(node) => nodes.push(node),
                Err(e) => debug!("skip {service}{path}: {e}"),
            }
        }

        if nodes.is_empty() {
            anyhow::bail!("no readable objects discovered");
        }

        wire_children(&mut nodes, ns.as_str());
        Ok(nodes)
    }

    async fn discover_service_paths(&self, conn: &Connection, service: &str) -> Vec<String> {
        let candidate_paths = candidate_object_manager_paths(service);
        let mut visited = HashSet::new();
        let mut queue = VecDeque::new();
        let mut discovered = Vec::new();

        for candidate in &candidate_paths {
            if visited.len() >= MAX_DISCOVERED_PATHS {
                break;
            }

            for path in self.via_object_manager(conn, service, candidate).await {
                if visited.len() >= MAX_DISCOVERED_PATHS {
                    break;
                }
                if self.should_skip_path(service, &path) {
                    continue;
                }
                if visited.insert(path.clone()) {
                    discovered.push(path);
                }
            }
        }

        for seed in candidate_paths {
            queue.push_back((seed, 0usize));
        }

        while let Some((path, depth)) = queue.pop_front() {
            if visited.len() >= MAX_DISCOVERED_PATHS || depth > MAX_DEPTH {
                continue;
            }
            if self.should_skip_path(service, &path) || !visited.insert(path.clone()) {
                continue;
            }

            let Ok(xml) = self.introspect_xml(conn, service, &path).await else {
                continue;
            };

            discovered.push(path.clone());
            for child in parse_child_nodes(&xml, &path) {
                if !visited.contains(&child) {
                    queue.push_back((child, depth + 1));
                }
            }
        }

        discovered.sort();
        discovered.dedup();
        discovered
    }

    async fn via_object_manager(
        &self,
        conn: &Connection,
        service: &str,
        path: &str,
    ) -> Vec<String> {
        use zbus::fdo::ObjectManagerProxy;

        let Ok(Ok(proxy)) = tokio::time::timeout(INTROSPECT_TIMEOUT, async {
            ObjectManagerProxy::builder(conn)
                .destination(service)?
                .path(path)?
                .build()
                .await
        }).await else {
            return Vec::new();
        };

        let Ok(Ok(objects)) = tokio::time::timeout(INTROSPECT_TIMEOUT, proxy.get_managed_objects()).await else {
            return Vec::new();
        };

        objects.keys().map(|p| p.as_str().to_string()).collect()
    }

    async fn introspect_xml(&self, conn: &Connection, service: &str, path: &str) -> Result<String> {
        tokio::time::timeout(INTROSPECT_TIMEOUT, async {
            IntrospectableProxy::builder(conn)
