// ── XML parser ────────────────────────────────────────────────────────────────

struct Parsed { interfaces: Vec<IfaceMeta>, children: Vec<String> }
struct IfaceMeta { name: String, has_properties: bool }

fn parse_xml(xml: &str, parent_path: &str) -> Parsed {
    use quick_xml::events::Event;
    use quick_xml::Reader;

    let mut reader = Reader::from_str(xml);
    reader.config_mut().trim_text(true);

    let mut interfaces = Vec::new();
    let mut children = Vec::new();
    let mut current_iface: Option<IfaceMeta> = None;
    let mut node_depth: usize = 0;

    loop {
        match reader.read_event() {
            Ok(Event::Start(e)) => match e.name().as_ref() {
                b"node" => {
                    if node_depth == 1 {
                        if let Some(attr) = e.attributes().flatten().find(|a| a.key.as_ref() == b"name") {
                            let child_name = String::from_utf8_lossy(&attr.value).to_string();
                            let child_path = join_child_path(parent_path, &child_name);
                            if !child_path.is_empty() {
                                children.push(child_path);
                            }
                        }
                    }
                    node_depth += 1;
                }
                b"interface" => {
                    if let Some(attr) = e.attributes().flatten().find(|a| a.key.as_ref() == b"name") {
                        current_iface = Some(IfaceMeta {
                            name: String::from_utf8_lossy(&attr.value).into_owned(),
                            has_properties: false,
                        });
                    }
                }
                b"property" => {
                    if let Some(ref mut iface) = current_iface {
                        iface.has_properties = true;
                    }
                }
                _ => {}
            },
            Ok(Event::Empty(e)) => match e.name().as_ref() {
                b"node" => {
                    if node_depth == 1 {
                        if let Some(attr) = e.attributes().flatten().find(|a| a.key.as_ref() == b"name") {
                            let child_name = String::from_utf8_lossy(&attr.value).to_string();
                            let child_path = join_child_path(parent_path, &child_name);
                            if !child_path.is_empty() {
                                children.push(child_path);
                            }
                        }
                    }
                }
                b"property" => {
                    if let Some(ref mut iface) = current_iface {
                        iface.has_properties = true;
                    }
                }
                _ => {}
            },
            Ok(Event::End(e)) => match e.name().as_ref() {
                b"interface" => {
                    if let Some(iface) = current_iface.take() {
                        interfaces.push(iface);
                    }
                }
                b"node" => {
                    node_depth = node_depth.saturating_sub(1);
                }
                _ => {}
            },
            Ok(Event::Eof) | Err(_) => break,
            _ => {}
        }
    }

    Parsed { interfaces, children }
}

fn parse_child_nodes(xml: &str, parent_path: &str) -> Vec<String> {
    parse_xml(xml, parent_path).children
}

fn join_child_path(parent_path: &str, child_name: &str) -> String {
    if child_name.is_empty() {
        return String::new();
    }
    if child_name.starts_with('/') {
        return child_name.to_string();
    }
    if parent_path == "/" {
        format!("/{child_name}")
    } else {
        format!("{parent_path}/{child_name}")
    }
}

async fn get_all_props(conn: &Connection, service: &str, path: &str, interface: &str) -> HashMap<String, String> {
    let Ok(Ok(proxy)) = tokio::time::timeout(INTROSPECT_TIMEOUT, async {
        zbus::Proxy::new(conn, service, path, "org.freedesktop.DBus.Properties").await
    }).await else { return HashMap::new(); };

    type PropMap = HashMap<String, OwnedValue>;
    let Ok(Ok(map)): Result<Result<PropMap, _>, _> =
        tokio::time::timeout(INTROSPECT_TIMEOUT, proxy.call("GetAll", &(interface,))).await
    else { return HashMap::new(); };

    map.into_iter().map(|(k, v)| (k, owned_value_to_json(&v))).collect()
}

fn owned_value_to_json(v: &OwnedValue) -> String {
    serde_json::to_value(v).map(|j| j.to_string()).unwrap_or_else(|_| format!("{v:?}"))
}

fn wire_children(nodes: &mut [NodeDescriptor], ns: &str) {
    let paths: Vec<String> = nodes.iter().map(|n| n.dbus_path.clone()).collect();
    let prefix = format!("/org/opdbus/projection/{ns}/");
    for node in nodes.iter_mut() {
        let my_depth = node.dbus_path.matches('/').count();
        node.children = paths.iter().filter(|p| {
            p.starts_with(&node.dbus_path) && p.len() > node.dbus_path.len()
                && p[node.dbus_path.len()..].starts_with('/')
                && p.matches('/').count() == my_depth + 1
                && p.starts_with(&prefix)
        }).cloned().collect();
    }
}

fn candidate_object_manager_paths(service: &str) -> Vec<String> {
    let mut paths = vec!["/".to_string()];
    let mut current_original = String::new();
    let mut current_lower = String::new();

    for part in service.split('.') {
        if part.is_empty() {
            continue;
        }

        current_original.push('/');
        current_original.push_str(part);
        if !paths.contains(&current_original) {
            paths.push(current_original.clone());
        }

        let lower = part.to_ascii_lowercase();
        current_lower.push('/');
        current_lower.push_str(&lower);
        if !paths.contains(&current_lower) {
            paths.push(current_lower.clone());
        }
    }

    paths
}

