use std::sync::Arc;
use std::time::Duration;

use anyhow::Result;
use tracing::info;
use tracing_subscriber::EnvFilter;

use op_procfs_plugin::ProcfsSource;
use op_projection::{ProjectionEngine, RegistrySource, SessionBusSource, StateDbSource, SystemBusSource};

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(
            EnvFilter::from_default_env()
                .add_directive("op_projection=info".parse()?)
                .add_directive("op_projection_daemon=info".parse()?),
        )
        .compact()
        .init();

    info!("op-projection-daemon starting");

    let engine = Arc::new(ProjectionEngine::new().await?);

    // ── Primary: authoritative persisted graph from state.db ─────────────────
    engine
        .register_primary(Arc::new(StateDbSource::with_default_database_url()))
        .await;

    // ── Primary: runtime registry metadata (supplements persisted graph) ─────
    let endpoint = std::env::var("REGISTRY_ENDPOINT")
        .unwrap_or_else(|_| "http://127.0.0.1:50051".into());
    let (registry, skiplist) = RegistrySource::new(endpoint);
    engine.register_primary(Arc::new(registry)).await;

    // ── Supplemental: system bus introspection ────────────────────────────────
    engine
        .register_supplemental(Arc::new(SystemBusSource::new(Arc::clone(&skiplist))))
        .await;

    // ── Supplemental: session bus (optional) ─────────────────────────────────
    if std::env::var("DBUS_SESSION_BUS_ADDRESS").is_ok() {
        engine
            .register_supplemental(Arc::new(SessionBusSource::new(Arc::clone(&skiplist))))
            .await;
    }

    // ── Supplemental: procfs ──────────────────────────────────────────────────
    engine.register_supplemental(Arc::new(ProcfsSource::new())).await;

    let interval = std::env::var("PROJECTION_INTERVAL_SECS")
        .ok()
        .and_then(|s| s.parse().ok())
        .map(Duration::from_secs)
        .unwrap_or(Duration::from_secs(30));

    engine.run(interval).await
}

