use std::collections::HashMap;

use anyhow::Result;
use op_projection::source::{NodeDescriptor, NodeType, projection_path};
use op_projection::lazy::LAZY_THRESHOLD;

const NS: &str = "procfs";

pub async fn discover() -> Result<Vec<NodeDescriptor>> {
    let mut nodes = Vec::new();
    let mut pids: Vec<u32> = Vec::new();

    let mut dir = tokio::fs::read_dir("/proc").await?;
    while let Ok(Some(entry)) = dir.next_entry().await {
        let name = entry.file_name();
        let s = name.to_string_lossy();
        if s.chars().all(|c| c.is_ascii_digit()) {
            if let Ok(pid) = s.parse::<u32>() {
                pids.push(pid);
            }
        }
    }

    // Large PID sets use lazy collection — avoids publishing thousands of objects.
    if pids.len() > LAZY_THRESHOLD {
        return Ok(build_lazy_collection(pids).await);
    }

    for pid in &pids {
        match read_process(*pid).await {
            Ok(node) => nodes.push(node),
            Err(_) => {} // process exited
        }
    }

    let children: Vec<String> = nodes.iter().map(|n| n.dbus_path.clone()).collect();
    nodes.push(NodeDescriptor {
        key: format!("{NS}::/processes"),
        source_path: "/proc".into(),
        dbus_path: projection_path(NS, "/processes"),
        node_type: NodeType::Directory,
        properties: HashMap::from([("_count".into(), nodes.len().to_string())]),
        children,
    });

    Ok(nodes)
}

async fn build_lazy_collection(pids: Vec<u32>) -> Vec<NodeDescriptor> {
    // Build entry map: pid_str → JSON summary (lightweight, no blocking reads).
    let mut props: HashMap<String, String> = HashMap::new();
    props.insert("_count".into(), pids.len().to_string());
    props.insert("_label".into(), "processes".into());

    // Populate entry.{pid} with a brief summary fetched concurrently.
    let handles: Vec<_> = pids.iter().map(|&pid| tokio::spawn(async move {
        let name = tokio::fs::read_to_string(format!("/proc/{pid}/comm"))
            .await
            .unwrap_or_default()
            .trim()
            .to_string();
        (pid, name)
    })).collect();

    for handle in handles {
        if let Ok((pid, name)) = handle.await {
            props.insert(
                format!("entry.{pid}"),
                serde_json::json!({ "pid": pid, "name": name }).to_string(),
            );
