#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(
            EnvFilter::from_default_env()
                .add_directive("op_projection=info".parse()?)
                .add_directive("op_projection_daemon=info".parse()?),
        )
        .compact()
        .init();

    info!("op-projection-daemon starting");

    let engine = Arc::new(ProjectionEngine::new().await?);

    // ── Primary: runtime registry metadata ───────────────────────────────────
    let endpoint =
        std::env::var("REGISTRY_ENDPOINT").unwrap_or_else(|_| "http://127.0.0.1:50051".into());
    let (registry, skiplist) = RegistrySource::new(endpoint);
    engine.register_primary(Arc::new(registry)).await;

    // ── Supplemental: system bus introspection ────────────────────────────────
    engine
        .register_supplemental(Arc::new(SystemBusSource::new(Arc::clone(&skiplist))))
