/// Infer column types from a value
fn infer_columns(value: &Value) -> Value {
    match value {
        Value::Object(map) => {
            let mut cols = simd_json::value::owned::Object::new();
            for (k, v) in map.iter() {
                cols.insert(k.clone(), json!({"type": infer_type(v)}));
            }
            Value::Object(Box::new(cols))
        }
        Value::Array(arr) => {
            if let Some(first) = arr.first() {
                infer_columns(first)
            } else {
                json!({})
            }
        }
        _ => json!({"value": {"type": infer_type(value)}}),
    }
}

/// Infer the type of a value
fn infer_type(value: &Value) -> &'static str {
    if value.is_null() {
        return "null";
    }
    if value.is_bool() {
        return "boolean";
    }
    if value.is_number() {
        return "integer";
    }
    if value.is_str() {
        return "string";
    }
    if value.is_array() {
        return "set";
    }
    if value.is_object() {
        return "map";
    }
    "unknown"
}

/// Convert a value to table rows
fn value_to_rows(value: &Value) -> Vec<Value> {
    match value {
        Value::Array(arr) => arr.clone(),
        Value::Object(map) => {
            // Check if there's an array field
            for (_, v) in map.iter() {
                if let Value::Array(arr) = v {
                    return arr.clone();
                }
            }
            // Return single row
            vec![value.clone()]
        }
        _ => vec![value.clone()],
    }
}

