+    NodeDescriptor {
+        key: format!("{NS}/{backend}::{db}/{table}/{row_key}"),
+        source_path: format!("{backend}::{db}/{table}/{row_key}"),
+        dbus_path: projection_path(NS, &format!("/{backend}/{db}/{table}/{row_key}")),
