struct BusSource {
    kind: BusKind,
    skiplist: Arc<DashSet<String>>,
}

impl BusSource {
    async fn connect(&self) -> Result<Connection> {
        match self.kind {
            BusKind::System => Connection::system().await.context("system bus"),
            BusKind::Session => Connection::session().await.context("session bus"),
        }
    }

    fn should_skip(&self, svc: &str) -> bool {
        if svc == "org.opdbus" {
            return false;
        }

        ALWAYS_SKIP_EXACT.contains(&svc)
            || ALWAYS_SKIP_PREFIXES
                .iter()
                .any(|prefix| svc.starts_with(prefix))
            || self.skiplist.contains(svc)
    }

    fn should_skip_path(&self, service: &str, path: &str) -> bool {
        // The legacy org.opdbus mirror at /org/opdbus/projected is already a
        // projection of other services. Re-projecting it duplicates objects
        // rather than exposing the real owned objects on the system.
        service == "org.opdbus"
            && (path == "/org/opdbus/projected" || path.starts_with("/org/opdbus/projected/"))
    }

    async fn discover(&self, namespace: &str) -> Result<Vec<NodeDescriptor>> {
        let conn = self.connect().await?;
        let dbus = DBusProxy::new(&conn).await?;
        let names = dbus.list_names().await?;
        let mut nodes = Vec::new();

        for name in names {
            let svc = name.as_str();
            if self.should_skip(svc) {
                continue;
            }
            match self.crawl_service(&conn, svc, namespace).await {
                Ok(mut discovered) => nodes.append(&mut discovered),
                Err(e) => debug!("skip {svc}: {e}"),
            }
        }
        Ok(nodes)
    }

    async fn crawl_service(
        &self,
        conn: &Connection,
        service: &str,
        namespace: &str,
    ) -> Result<Vec<NodeDescriptor>> {
        let ns = format!("{}/{}", namespace, escape_service_name(service));
        let paths = self.discover_service_paths(conn, service).await;
        let mut nodes = Vec::new();

        for path in paths {
            if self.should_skip_path(service, &path) {
                continue;
            }

            match self.introspect_nodes(conn, service, &path, &ns).await {
                Ok(mut discovered) => nodes.append(&mut discovered),
                Err(e) => debug!("skip {service}{path}: {e}"),
