                if visited.insert(path.clone()) {
                    discovered.push(path);
                }
            }
        }

        for seed in candidate_paths {
            queue.push_back((seed, 0usize));
        }

        while let Some((path, depth)) = queue.pop_front() {
            if visited.len() >= MAX_DISCOVERED_PATHS || depth > MAX_DEPTH {
                continue;
            }
