struct Parsed {
    interfaces: Vec<IfaceMeta>,
    children: Vec<String>,
    methods: Vec<MethodMeta>,
}

struct IfaceMeta {
    name: String,
    has_properties: bool,
}

struct MethodMeta {
    interface: String,
    name: String,
    in_signature: String,
    out_signature: String,
}

fn parse_xml(xml: &str, parent_path: &str) -> Parsed {
    use quick_xml::events::Event;
    use quick_xml::Reader;

    let mut reader = Reader::from_str(xml);
    reader.config_mut().trim_text(true);

    let mut interfaces = Vec::new();
    let mut children = Vec::new();
    let mut methods = Vec::new();
    let mut current_iface: Option<IfaceMeta> = None;
    let mut current_iface_name: Option<String> = None;
    let mut current_method: Option<MethodMeta> = None;
    let mut node_depth: usize = 0;

    loop {
        match reader.read_event() {
            Ok(Event::Start(e)) => match e.name().as_ref() {
                b"node" => {
                    if node_depth == 1 {
                        if let Some(attr) =
                            e.attributes().flatten().find(|a| a.key.as_ref() == b"name")
                        {
                            let child_name = String::from_utf8_lossy(&attr.value).to_string();
                            let child_path = join_child_path(parent_path, &child_name);
                            if !child_path.is_empty() {
                                children.push(child_path);
                            }
                        }
                    }
                    node_depth += 1;
                }
                b"interface" => {
                    if let Some(attr) = e.attributes().flatten().find(|a| a.key.as_ref() == b"name")
                    {
                        let name = String::from_utf8_lossy(&attr.value).into_owned();
                        current_iface_name = Some(name.clone());
                        current_iface = Some(IfaceMeta {
                            name,
                            has_properties: false,
                        });
                    }
                }
                b"method" => {
                    if let (Some(interface), Some(attr)) = (
                        current_iface_name.clone(),
                        e.attributes().flatten().find(|a| a.key.as_ref() == b"name"),
                    ) {
                        current_method = Some(MethodMeta {
                            interface,
                            name: String::from_utf8_lossy(&attr.value).into_owned(),
                            in_signature: String::new(),
                            out_signature: String::new(),
                        });
                    }
                }
                b"arg" => {
                    append_arg_signature(&mut current_method, &e);
                }
                b"property" => {
                    if let Some(ref mut iface) = current_iface {
                        iface.has_properties = true;
                    }
                }
                _ => {}
            },
            Ok(Event::Empty(e)) => match e.name().as_ref() {
                b"node" => {
                    if node_depth == 1 {
                        if let Some(attr) =
                            e.attributes().flatten().find(|a| a.key.as_ref() == b"name")
                        {
                            let child_name = String::from_utf8_lossy(&attr.value).to_string();
                            let child_path = join_child_path(parent_path, &child_name);
                            if !child_path.is_empty() {
                                children.push(child_path);
                            }
                        }
                    }
                }
                b"property" => {
                    if let Some(ref mut iface) = current_iface {
                        iface.has_properties = true;
                    }
                }
                b"arg" => {
                    append_arg_signature(&mut current_method, &e);
                }
                _ => {}
            },
            Ok(Event::End(e)) => match e.name().as_ref() {
                b"method" => {
                    if let Some(method) = current_method.take() {
                        methods.push(method);
                    }
                }
                b"interface" => {
                    if let Some(iface) = current_iface.take() {
                        interfaces.push(iface);
                    }
                    current_iface_name = None;
                }
                b"node" => {
                    node_depth = node_depth.saturating_sub(1);
                }
                _ => {}
