            "{service}::{object_path}::{}::{}",
            method.interface, method.name
        ),
        dbus_path,
        node_type: NodeType::RpcCall,
        properties,
        children: Vec::new(),
    }
}

fn rpc_call_path(ns: &str, object_path: &str, interface: &str, method: &str) -> String {
    let leaf = format!("rpc_{}_{}", path_segment(interface), path_segment(method));
    let method_path = if object_path == "/" {
        format!("/{leaf}")
    } else {
        format!("{object_path}/{leaf}")
    };
    projection_path(ns, &method_path)
}

fn path_segment(value: &str) -> String {
    value
        .chars()
        .map(|c| match c {
            'A'..='Z' | 'a'..='z' | '0'..='9' | '_' => c,
            _ => '_',
        })
        .collect()
}

async fn get_all_props(
    conn: &Connection,
    service: &str,
    path: &str,
    interface: &str,
) -> HashMap<String, String> {
    let Ok(Ok(proxy)) = tokio::time::timeout(INTROSPECT_TIMEOUT, async {
        zbus::Proxy::new(conn, service, path, "org.freedesktop.DBus.Properties").await
    })
    .await
    else {
        return HashMap::new();
    };

    type PropMap = HashMap<String, OwnedValue>;
    let Ok(Ok(map)): Result<Result<PropMap, _>, _> =
        tokio::time::timeout(INTROSPECT_TIMEOUT, proxy.call("GetAll", &(interface,))).await
    else {
        return HashMap::new();
    };

    map.into_iter()
        .map(|(k, v)| (k, owned_value_to_json(&v)))
        .collect()
}

fn owned_value_to_json(v: &OwnedValue) -> String {
    serde_json::to_value(v)
        .map(|j| j.to_string())
        .unwrap_or_else(|_| format!("{v:?}"))
}

fn wire_children(nodes: &mut [NodeDescriptor], ns: &str) {
    let paths: Vec<String> = nodes.iter().map(|n| n.dbus_path.clone()).collect();
    let prefix = format!("/org/opdbus/projection/{ns}/");
    for node in nodes.iter_mut() {
        let my_depth = node.dbus_path.matches('/').count();
        node.children = paths
            .iter()
            .filter(|p| {
                p.starts_with(&node.dbus_path)
                    && p.len() > node.dbus_path.len()
                    && p[node.dbus_path.len()..].starts_with('/')
                    && p.matches('/').count() == my_depth + 1
                    && p.starts_with(&prefix)
            })
            .cloned()
            .collect();
    }
}

fn candidate_object_manager_paths(service: &str) -> Vec<String> {
    let mut paths = vec!["/".to_string()];
    let mut current_original = String::new();
    let mut current_lower = String::new();

    for part in service.split('.') {
        if part.is_empty() {
            continue;
        }

        current_original.push('/');
        current_original.push_str(part);
        if !paths.contains(&current_original) {
            paths.push(current_original.clone());
        }

        let lower = part.to_ascii_lowercase();
        current_lower.push('/');
        current_lower.push_str(&lower);
        if !paths.contains(&current_lower) {
            paths.push(current_lower.clone());
        }
    }

    paths
}

